#!/usr/bin/env python3
import hashlib, hmac, json, os, pathlib, ssl, subprocess, sys, time, urllib.parse
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

HERE = pathlib.Path(__file__).resolve().parent
CAMPAIGN_ROOT = pathlib.Path(os.environ.get('CFD_CAMPAIGN_ROOT', HERE.parent)).resolve()
TOKEN_ENV = 'CFD_CONTROLLER_TOKEN'
TAIL_LINES = 200
EVENT_HEARTBEAT_SECONDS = 15
TOKEN_FILE_ENV = 'CFD_CONTROLLER_TOKEN_FILE'
REQUIRE_AUTH = True
TLS_ENABLED = True
TLS_CERT_ENV = 'CFD_CONTROLLER_TLS_CERT'
TLS_KEY_ENV = 'CFD_CONTROLLER_TLS_KEY'
HISTORY_ENABLED = True
MAX_HISTORY_BYTES = 10485760
LIVE_PROBES_ENABLED = True
PROBE_TIMEOUT_SECONDS = 15
ALLOW_MUTATION = True
REQUIRE_TOKEN = True
ACTIONS = set(['stop', 'flush'])

def read_status():
    path = HERE / 'status.json'
    if not path.exists():
        return {'schema': 'cfd.multiserver.controller.status.v1', 'summary': {'cases': 0}, 'cases': []}
    return json.loads(path.read_text(encoding='utf-8'))

def append_history(event, payload):
    if not HISTORY_ENABLED:
        return
    path = HERE / 'events-history.ndjson'
    record = json.dumps({'time_ns': time.time_ns(), 'event': event, 'payload': payload}, separators=(',', ':')) + '\n'
    if path.exists() and path.stat().st_size + len(record.encode('utf-8')) > MAX_HISTORY_BYTES:
        rotated = HERE / 'events-history.ndjson.1'
        path.replace(rotated)
    with path.open('a', encoding='utf-8') as stream:
        stream.write(record)

def reply(handler, code, obj, content_type='application/json'):
    data = json.dumps(obj, indent=2).encode('utf-8') if not isinstance(obj, (bytes, bytearray)) else obj
    handler.send_response(code)
    handler.send_header('Content-Type', content_type)
    handler.send_header('Content-Length', str(len(data)))
    handler.end_headers()
    handler.wfile.write(data)

def authorized(handler, required_role='viewer'):
    if not REQUIRE_AUTH and not REQUIRE_TOKEN:
        return True
    header = handler.headers.get('Authorization', '')
    query = urllib.parse.parse_qs(urllib.parse.urlparse(handler.path).query)
    raw = header[7:] if header.startswith('Bearer ') else query.get('token', [''])[0]
    legacy = os.environ.get(TOKEN_ENV, '')
    if legacy and hmac.compare_digest(raw, legacy):
        return True
    token_path = pathlib.Path(os.environ.get(TOKEN_FILE_ENV, HERE / 'controller.tokens.json'))
    try:
        entries = json.loads(token_path.read_text(encoding='utf-8')).get('tokens', [])
    except (OSError, ValueError):
        return False
    digest = hashlib.sha256(raw.encode('utf-8')).hexdigest()
    levels = {'viewer': 0, 'operator': 1, 'admin': 2}
    for entry in entries:
        if hmac.compare_digest(digest, str(entry.get('sha256', ''))) and levels.get(entry.get('role'), -1) >= levels[required_role]:
            return True
    return False

def tail(path_text, lines):
    path = pathlib.Path(path_text)
    if not path.is_absolute():
        path = CAMPAIGN_ROOT / path
    try:
        buf = path.read_text(errors='replace').splitlines()
        return '\n'.join(buf[-lines:]) + ('\n' if buf else '')
    except OSError as exc:
        return 'log unavailable: %s\n' % exc

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        parts = [p for p in parsed.path.split('/') if p]
        status = read_status()
        if parsed.path in ('/', '/index.html'):
            data = (HERE / 'index.html').read_bytes()
            reply(self, 200, data, 'text/html; charset=utf-8')
            return
        if parsed.path == '/dashboard.js':
            data = (HERE / 'dashboard.js').read_bytes()
            reply(self, 200, data, 'application/javascript; charset=utf-8')
            return
        if parsed.path == '/dashboard.css':
            data = (HERE / 'dashboard.css').read_bytes()
            reply(self, 200, data, 'text/css; charset=utf-8')
            return
        if parsed.path == '/api/events':
            path = HERE / 'events.ndjson'
            data = path.read_bytes() if path.exists() else b''
            reply(self, 200, data, 'application/x-ndjson; charset=utf-8')
            return
        if parsed.path == '/api/health':
            reply(self, 200, {'ok': True, 'schema': 'cfd.multiserver.controller.health.v1'})
            return
        if parsed.path == '/api/status':
            reply(self, 200, status)
            return
        if parsed.path == '/api/cases':
            reply(self, 200, {'cases': status.get('cases', [])})
            return
        if len(parts) == 5 and parts[:2] == ['api', 'cases'] and parts[3] == 'logs':
            case_id, stream = parts[2], parts[4]
            for case in status.get('cases', []):
                if case.get('case_id') == case_id and stream in ('stdout', 'stderr'):
                    data = tail(case.get(stream, ''), TAIL_LINES).encode('utf-8')
                    reply(self, 200, data, 'text/plain; charset=utf-8')
                    return
            reply(self, 404, {'error': 'case or log stream not found'})
            return
        reply(self, 404, {'error': 'not found'})

    def do_POST(self):
        parsed = urllib.parse.urlparse(self.path)
        parts = [p for p in parsed.path.split('/') if p]
        if len(parts) == 5 and parts[:2] == ['api', 'cases'] and parts[3] == 'control':
            if not ALLOW_MUTATION:
                reply(self, 403, {'error': 'mutations disabled'})
                return
            if not authorized(self):
                reply(self, 401, {'error': 'missing or invalid controller token'})
                return
            case_id, action = parts[2], parts[4]
            if action not in ACTIONS:
                reply(self, 400, {'error': 'unsupported action'})
                return
            control_dir = CAMPAIGN_ROOT / case_id / '.cfd_control'
            control_dir.mkdir(parents=True, exist_ok=True)
            body = 'case_id=%s\naction=%s\nreason=controller-api\n' % (case_id, action)
            (control_dir / (action + '.directive')).write_text(body, encoding='utf-8')
            (control_dir / 'latest.directive').write_text(body, encoding='utf-8')
            reply(self, 202, {'ok': True, 'case_id': case_id, 'action': action})
            return
        reply(self, 404, {'error': 'not found'})

    def log_message(self, fmt, *args):
        sys.stderr.write('controller: ' + fmt % args + '\n')

def sse_frame(event, payload, event_id):
    data = json.dumps(payload, separators=(',', ':'))
    return ('id: %s\nevent: %s\ndata: %s\n\n' % (event_id, event, data)).encode('utf-8')

class StreamingHandler(Handler):
    protocol_version = 'HTTP/1.1'

    def do_GET(self):
        if urllib.parse.urlparse(self.path).path != '/api/events/stream':
            return super().do_GET()
        self.send_response(200)
        self.send_header('Content-Type', 'text/event-stream; charset=utf-8')
        self.send_header('Cache-Control', 'no-cache')
        self.send_header('Connection', 'keep-alive')
        self.end_headers()
        event_id = 0
        last_payload = None
        try:
            while True:
                payload = read_status()
                encoded = json.dumps(payload, sort_keys=True)
                if encoded != last_payload:
                    event_id += 1
                    self.wfile.write(sse_frame('status', payload, event_id))
                    last_payload = encoded
                else:
                    self.wfile.write(b': heartbeat\n\n')
                self.wfile.flush()
                time.sleep(EVENT_HEARTBEAT_SECONDS)
        except (BrokenPipeError, ConnectionResetError):
            return

class ProductionHandler(StreamingHandler):
    def reject_auth(self):
        reply(self, 401, {'error': 'authentication required'})

    def do_GET(self):
        path = urllib.parse.urlparse(self.path).path
        if path.startswith('/api/') and path != '/api/health' and not authorized(self, 'viewer'):
            return self.reject_auth()
        if path == '/api/events/history':
            history = HERE / 'events-history.ndjson'
            return reply(self, 200, history.read_bytes() if history.exists() else b'', 'application/x-ndjson; charset=utf-8')
        if path == '/api/probes':
            if not LIVE_PROBES_ENABLED:
                return reply(self, 403, {'error': 'live probes disabled'})
            script = HERE.parent / 'multiserver_access_checks.sh'
            try:
                run = subprocess.run([str(script)], cwd=HERE.parent, capture_output=True, text=True, timeout=PROBE_TIMEOUT_SECONDS, check=False)
                payload = {'ok': run.returncode == 0, 'exit_code': run.returncode, 'stdout': run.stdout[-8192:], 'stderr': run.stderr[-8192:]}
            except (OSError, subprocess.TimeoutExpired) as exc:
                payload = {'ok': False, 'error': str(exc)}
            append_history('probe', payload)
            return reply(self, 200 if payload.get('ok') else 503, payload)
        return super().do_GET()

    def do_POST(self):
        if not authorized(self, 'operator'):
            return self.reject_auth()
        append_history('control-request', {'path': urllib.parse.urlparse(self.path).path})
        return super().do_POST()

if __name__ == '__main__':
    host = os.environ.get('CFD_CONTROLLER_HOST', '127.0.0.1')
    port = int(os.environ.get('CFD_CONTROLLER_PORT', '9443'))
    server = ThreadingHTTPServer((host, port), ProductionHandler)
    if TLS_ENABLED:
        cert = os.environ.get(TLS_CERT_ENV, '')
        key = os.environ.get(TLS_KEY_ENV, '')
        if not cert or not key:
            raise SystemExit('TLS enabled but certificate/key environment variables are missing')
        context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        context.minimum_version = ssl.TLSVersion.TLSv1_2
        context.load_cert_chain(cert, key)
        server.socket = context.wrap_socket(server.socket, server_side=True)
    print('serving cfd controller on %s:%d campaign_root=%s tls=%s' % (host, port, CAMPAIGN_ROOT, TLS_ENABLED))
    server.serve_forever()

